"""Independent v0.2 research output. Never replaces either active score model."""
import json,pickle,hashlib,sys
from pathlib import Path
from datetime import datetime,timezone
import numpy as np
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from upset_v2 import features as ft
# Import defines TorchModel for loading only artifacts generated by our own training.
from upset_v2 import train as training

def run(fixture,registry_path='/workspace/WCPP/runtime/upset-candidates.json'):
 base={'version':training.VERSION,'match_id':fixture['match_id'],'main_score_reordered':False,'formal_kpi_eligible':False}
 p=Path(registry_path)
 if not p.exists():return dict(base,status='ABSTAIN_NO_CANDIDATE_REGISTRY')
 reg=json.loads(p.read_text());route=reg.get('models',{}).get(fixture['cohort'])
 if not route:return dict(base,status='ABSTAIN_NO_TRAINED_COHORT')
 quote=fixture.get('wdl_quote')
 if not quote:return dict(base,status='ABSTAIN_MISSING_1X2_QUOTE')
 old=ft.old;cutoff=old.aware(fixture['cutoff_at']);kickoff=old.aware(fixture['kickoff_at']);now=datetime.now(timezone.utc)
 if not cutoff<=now<kickoff:raise ValueError('future forecast only')
 from urllib.parse import urlparse
 if quote.get('match_id')!=fixture['match_id'] or quote.get('market')!='1x2' or quote.get('verified') is not True or not quote.get('bookmaker'):raise ValueError('verified same-match named quote required')
 u=urlparse(quote.get('source_url',''))
 if u.scheme!='https' or not u.netloc or u.username or u.password:raise ValueError('HTTPS quote required')
 qt=old.aware(quote['query_time'])
 if qt>cutoff or quote.get('quoted_at') and old.aware(quote['quoted_at'])>min(qt,cutoff):raise ValueError('future quote')
 odds=[quote[k] for k in ('home_odds','draw_odds','away_odds')];fav=old.favorite(odds)
 if not fav:return dict(base,status='ABSTAIN_NO_STRONG_MARKET_FAVORITE')
 if fixture.get('neutral') is not False:return dict(base,status='ABSTAIN_NEUTRAL_VENUE_SCOPE')
 ap=Path(route['artifact_path']).resolve();trusted=Path('/workspace/WCPP/models').resolve()
 if not ap.is_relative_to(trusted) or hashlib.sha256(ap.read_bytes()).hexdigest()!=route['artifact_sha256']:raise ValueError('trusted local candidate checksum required')
 # Never load external pickle; registry must refer only to our preserved local training output.
 # Training CLI executed as main requires resolving its locally defined class on load.
 import __main__
 __main__.TorchModel=training.TorchModel
 a=pickle.loads(ap.read_bytes())
 if a['code_hash']!=training.CODE_HASH or a['cohort']!=fixture['cohort'] or old.aware(a['built_at'])>cutoff:raise ValueError('artifact or cutoff mismatch')
 rows=old.history_validate(a['history']);state=ft.State();date=min(cutoff.date().isoformat(),kickoff.date().isoformat())
 from itertools import groupby
 for day,g in groupby(rows,key=lambda r:r['date']):
  if day<date:state.update(list(g))
 side,market=fav;market=market[[0,1,2] if side=='home' else [2,1,0]][None,:];x=state.features(dict(fixture,date=date),odds)[None,:];chosen=a['selection'];x[:,a['untrained_columns']]=np.nan
 if a['model'] is None:p=market
 else:p=training.normalized(((1-chosen['alpha'])*market+chosen['alpha']*a['model'].predict_proba(x[:,a['columns']]))**(1/chosen['temperature']))
 return dict(base,status='CANDIDATE_SHADOW_ONLY',cohort=fixture['cohort'],favorite_side=side,probabilities=dict(zip(old.CLASSES,map(float,p[0]))),favorite_nonwin_probability=float(p[0,1]+p[0,2]),risk_label='UNVALIDATED_NO_ACTION_ALERT',acceptance_gate_passed=False,selected_model=chosen['name'],artifact_sha256=route['artifact_sha256'],untrained_features_masked=[ft.FEATURES[j] for j in a['untrained_columns']],data_cutoff=fixture['cutoff_at'],generated_at=now.isoformat(),kickoff_at=fixture['kickoff_at'],market_quote=quote,validation='REUSED_INSPECTED_TEST_DEVELOPMENT_ONLY',missing_modules=['historical_lineups','injuries','mathematical_motivation','full_schedule','integrity'])
if __name__=='__main__':
 import argparse
 p=argparse.ArgumentParser();p.add_argument('fixture');p.add_argument('--out',required=True);p.add_argument('--registry');a=p.parse_args();r=run(json.loads(Path(a.fixture).read_text()),a.registry) if a.registry else run(json.loads(Path(a.fixture).read_text()))
 with Path(a.out).open('x') as f:json.dump(r,f,ensure_ascii=False,indent=2,allow_nan=False)
